-- Controllers and their components, from 'Controllers_Data_Entry_(9_22_26).xlsx'
-- =============================================================================
-- 5,975 catalogue items: 5,840 CONTROLLER models and the 135 components the controller
-- BOMs are built from. Written to be run on any Lightspeed database - every setup row is
-- looked up by CODE, never by id, and the script stops before writing if one is missing.
--
-- What it writes, per item:
--   tbl_setup_item                              name/class/brand/uom by code, item_model,
--                                               item_code = MAX(item_code)+1 upward
--   tbl_setup_item_trade_type                   trade type TRD
--   tbl_setup_item_additional_specs             long_description, and for a controller the
--                                               PUMP COUNT COMPATABILITY
--   tbl_setup_item_additional_specs_pump_type   the controller's PUMP TYPE COMPATABILITY
--   tbl_setup_item_specs (+ _specs_template)    template CONTROLLER, for controllers only
--
-- Two notes on the spec template, because the workbook and the form disagree:
--
--   * The workbook's '# OF PUMP/S' and 'USE TYPE' sheets are NOT written as template rows.
--     Both are exact duplicates of a field that already has a home: # OF PUMP/S is the pump
--     count (1=SMP, 2=DPX, 3=TPX, 4=QPX, 5=QPX2) and USE TYPE is the pump type
--     (BOOSTER=BP, DRAINAGE=DP, TRANSFER=TP, CPS=CPS) - 5,840 rows each, agreeing 1:1 with
--     no exceptions. They go to pump_count_compatability_id and the pump-type table, which
--     is where Item Entry reads them. The two titles were removed from the CONTROLLER
--     template on 2026-09-19 for this reason (ENUM_ITEM_SPECS.CONTROLLER).
--
--   * The template is written with all six titles the form uses, in the form's order.
--     MODEL and WIRING DIAGRAM # are written empty because the workbook does not carry
--     them - exactly what saving a new controller from Item Entry produces.
--
-- Run again safely: an item whose BRAND + ITEM MODEL is already there is skipped and
-- reported, and nothing existing is updated or deleted.
--
-- The BOMs are a separate script (load_controllers_bom_*.sql) and need this one first.
--
-- HOW TO RUN: sqlcmd -S <server> -d <database> -b -i <this file>  (or open it in SSMS).
-- With @commit = 0 everything is done and counted, then rolled back. Set @commit = 1 to
-- keep it. After a commit, restart that database's API or clear its Redis keys - item
-- lists are cached for up to an hour.

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @commit bit = 0;   -- 1 = keep the changes, 0 = trial run

IF OBJECT_ID('tempdb..#src')   IS NOT NULL DROP TABLE #src;
IF OBJECT_ID('tempdb..#map')   IS NOT NULL DROP TABLE #map;
IF OBJECT_ID('tempdb..#aspec') IS NOT NULL DROP TABLE #aspec;
IF OBJECT_ID('tempdb..#specs') IS NOT NULL DROP TABLE #specs;

CREATE TABLE #src (
    row_no           int NOT NULL PRIMARY KEY,
    name_code        nvarchar(50)  NOT NULL,
    class_code       nvarchar(50)  NOT NULL,
    brand_code       nvarchar(50)  NOT NULL,
    uom_code         nvarchar(50)  NOT NULL,
    item_model       nvarchar(400) NOT NULL,
    long_description nvarchar(1000) NOT NULL,
    is_controller    bit NOT NULL,
    voltage          nvarchar(50) NOT NULL,
    current_a        nvarchar(50) NOT NULL,
    start_method     nvarchar(50) NOT NULL,
    phase            nvarchar(50) NOT NULL,
    pump_type_code   nvarchar(50) NOT NULL,
    pump_count_code  nvarchar(50) NOT NULL,
    item_id          bigint NULL,     -- filled for a row that is already in the catalogue
    item_code        nvarchar(50) NULL
);
CREATE TABLE #map   (row_no int PRIMARY KEY, item_id  bigint NOT NULL);
CREATE TABLE #aspec (row_no int PRIMARY KEY, specs_id bigint NOT NULL);
CREATE TABLE #specs (row_no int PRIMARY KEY, specs_id bigint NOT NULL);

-- The workbook ------------------------------------------------------------------













-- Everything this needs must already be in Setup ---------------------------------
-- Reported and refused rather than guessed at: a missing brand would otherwise land
-- 5,840 items under no brand at all.

IF OBJECT_ID('tempdb..#unresolved') IS NOT NULL DROP TABLE #unresolved;
CREATE TABLE #unresolved (setup_list nvarchar(60), code nvarchar(50));

SELECT DISTINCT N'Item Name', s.name_code FROM #src s
 WHERE NOT EXISTS (SELECT 1 FROM tbl_setup_item_name t WHERE t.code = s.name_code)
UNION ALL
SELECT DISTINCT N'Item Class', s.class_code FROM #src s
 WHERE NOT EXISTS (SELECT 1 FROM tbl_setup_item_class t WHERE t.code = s.class_code)
UNION ALL
SELECT DISTINCT N'Item Brand', s.brand_code FROM #src s
 WHERE NOT EXISTS (SELECT 1 FROM tbl_setup_item_brand t WHERE t.code = s.brand_code)
UNION ALL
SELECT DISTINCT N'Unit of Measure', s.uom_code FROM #src s
 WHERE NOT EXISTS (SELECT 1 FROM tbl_setup_item_unit_measurement t WHERE t.code = s.uom_code)
UNION ALL
SELECT DISTINCT N'Pump Type', s.pump_type_code FROM #src s
 WHERE s.is_controller = 1
   AND NOT EXISTS (SELECT 1 FROM tbl_setup_item_pump_type t WHERE t.code = s.pump_type_code)
UNION ALL
SELECT DISTINCT N'Pump Count', s.pump_count_code FROM #src s
 WHERE s.is_controller = 1
   AND NOT EXISTS (SELECT 1 FROM tbl_setup_item_pump_count t WHERE t.code = s.pump_count_code)
UNION ALL
SELECT N'Item Type (trade)', N'TRD'
 WHERE NOT EXISTS (SELECT 1 FROM tbl_setup_item_type WHERE code = N'TRD');

IF EXISTS (SELECT 1 FROM #unresolved)
BEGIN
    SELECT 'missing from Setup - nothing was written' AS problem, setup_list, code FROM #unresolved;
    RAISERROR('Setup rows are missing (listed above). Add them, then run this again.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

DECLARE @trade_id bigint = (SELECT id FROM tbl_setup_item_type WHERE code = N'TRD');

-- Already in the catalogue? Matched on brand + model, which is how an item is identified
-- here: the same model may legitimately exist under two brands (spec invariant 12).
UPDATE s
   SET s.item_id = i.id
  FROM #src s
  JOIN tbl_setup_item i
    ON i.item_model = s.item_model
  JOIN tbl_setup_item_brand b
    ON b.id = i.item_brand_id AND b.code = s.brand_code;

-- item_code continues from the highest one issued and never reuses a gap - the rule
-- generateItemCode() enforces in item_service.go.
DECLARE @next int = ISNULL((SELECT MAX(TRY_CAST(item_code AS int)) FROM tbl_setup_item), 0) + 1;

WITH numbered AS (
    SELECT item_code, ROW_NUMBER() OVER (ORDER BY row_no) AS rn
      FROM #src WHERE item_id IS NULL
)
UPDATE numbered SET item_code = CAST(@next + rn - 1 AS nvarchar(50));

-- 1. The items ------------------------------------------------------------------
MERGE tbl_setup_item AS t
USING (
    SELECT s.row_no, s.item_model, s.item_code,
           n.id AS name_id, c.id AS class_id, b.id AS brand_id, u.id AS uom_id
      FROM #src s
      JOIN tbl_setup_item_name             n ON n.code = s.name_code
      JOIN tbl_setup_item_class            c ON c.code = s.class_code
      JOIN tbl_setup_item_brand            b ON b.code = s.brand_code
      JOIN tbl_setup_item_unit_measurement u ON u.code = s.uom_code
     WHERE s.item_id IS NULL
) AS x
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (item_name_id, item_class_id, item_brand_id, unit_of_measure_id, item_model,
            catalogue_year, item_code, item_tangibility_type, is_stop_selling, price)
    VALUES (x.name_id, x.class_id, x.brand_id, x.uom_id, x.item_model,
            N'', x.item_code, N'TANGIBLE', 0, 0)
OUTPUT inserted.id, x.row_no INTO #map (item_id, row_no);

UPDATE s SET s.item_id = m.item_id FROM #src s JOIN #map m ON m.row_no = s.row_no;

-- 2. Trade type -----------------------------------------------------------------
-- tbl_setup_item_trade_type, which is what CreateItemTradeTypes writes and what Item
-- Entry reads. (The older tbl_item_trade_type is not written; nothing reads it now.)
SELECT s.item_id, @trade_id FROM #src s JOIN #map m ON m.row_no = s.row_no;

-- 3. Additional specs: long description, and the controller's pump count ---------
MERGE tbl_setup_item_additional_specs AS t
USING (
    SELECT s.row_no, s.item_id, s.long_description,
           CASE WHEN s.is_controller = 1 THEN pc.id ELSE NULL END AS pump_count_id
      FROM #src s
      JOIN #map m ON m.row_no = s.row_no
      LEFT JOIN tbl_setup_item_pump_count pc ON pc.code = s.pump_count_code
) AS x
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (based_id, long_description, pump_count_compatability_id)
    VALUES (x.item_id, x.long_description, x.pump_count_id)
OUTPUT inserted.id, x.row_no INTO #aspec (specs_id, row_no);

-- 4. The controller's pump type -------------------------------------------------
SELECT a.specs_id, pt.id
  FROM #aspec a
  JOIN #src s ON s.row_no = a.row_no
  JOIN tbl_setup_item_pump_type pt ON pt.code = s.pump_type_code
 WHERE s.is_controller = 1;

-- 5. The CONTROLLER spec template -----------------------------------------------
MERGE tbl_setup_item_specs AS t
USING (
    SELECT s.row_no, s.item_id
      FROM #src s JOIN #map m ON m.row_no = s.row_no
     WHERE s.is_controller = 1
) AS x
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (based_id, template, fla_1, fla_2, volt_1, volt_2, impeller_id, manufacturer_origin)
    VALUES (x.item_id, N'CONTROLLER', N'', N'', N'', N'', 0, N'')
OUTPUT inserted.id, x.row_no INTO #specs (specs_id, row_no);

SELECT sp.specs_id,
       t.title,
       CASE t.title
            WHEN N'VOLTAGE'        THEN s.voltage
            WHEN N'CURRENT'        THEN s.current_a
            WHEN N'START METHOD'   THEN s.start_method
            WHEN N'PHASE (1 OR 3)' THEN s.phase
            ELSE N''
       END
  FROM #specs sp
  JOIN #src s ON s.row_no = sp.row_no
  CROSS JOIN (VALUES (1, N'MODEL'), (2, N'VOLTAGE'), (3, N'CURRENT'),
                     (4, N'START METHOD'), (5, N'PHASE (1 OR 3)'),
                     (6, N'WIRING DIAGRAM #')) AS t(ord, title);

-- What happened -----------------------------------------------------------------
SELECT (SELECT COUNT(*) FROM #src)                          AS in_workbook,
       (SELECT COUNT(*) FROM #map)                          AS items_added,
       (SELECT COUNT(*) FROM #src WHERE row_no NOT IN (SELECT row_no FROM #map)) AS already_there,
       (SELECT COUNT(*) FROM #specs)                        AS controller_specs,
       (SELECT COUNT(*) FROM tbl_setup_item_specs_template t
          JOIN #specs sp ON sp.specs_id = t.based_id)       AS template_rows,
       (SELECT COUNT(*) FROM #aspec)                        AS additional_specs,
       (SELECT MIN(TRY_CAST(item_code AS int)) FROM #src WHERE row_no IN (SELECT row_no FROM #map)) AS first_item_code,
       (SELECT MAX(TRY_CAST(item_code AS int)) FROM #src WHERE row_no IN (SELECT row_no FROM #map)) AS last_item_code;

SELECT 'already in the catalogue, left alone' AS state, s.brand_code, s.item_model, s.item_id
  FROM #src s WHERE s.row_no NOT IN (SELECT row_no FROM #map)
 ORDER BY s.brand_code, s.item_model;

IF @commit = 1
BEGIN
    COMMIT TRANSACTION;
    PRINT 'committed';
END
ELSE
BEGIN
    ROLLBACK TRANSACTION;
    PRINT 'rolled back - set @commit = 1 to write';
END

IF OBJECT_ID('tempdb..#src')        IS NOT NULL DROP TABLE #src;
IF OBJECT_ID('tempdb..#map')        IS NOT NULL DROP TABLE #map;
IF OBJECT_ID('tempdb..#aspec')      IS NOT NULL DROP TABLE #aspec;
IF OBJECT_ID('tempdb..#specs')      IS NOT NULL DROP TABLE #specs;
IF OBJECT_ID('tempdb..#unresolved') IS NOT NULL DROP TABLE #unresolved;
